code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            boxes = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    b = boxes[color]
                    b[0], b[1] = min(b[0], y), max(b[1], y)
                    b[2], b[3] = min(b[2], x), max(b[3], x)
            ordered = sorted(boxes, key=lambda color: (-(boxes[color][1]-boxes[color][0]+1)*(boxes[color][3]-boxes[color][2]+1), color))
            mapping = {color: ordered[len(ordered)-1-i] for i, color in enumerate(ordered)}
            for y, x in cells:
                out[y][x] = mapping[grid[y][x]]
    return out
'''
